package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** A dated setting is recorded from its from-date, else from the sheet's today. */
public class SaveSettings {
    public void save(@Val SettingsChange change, Settings settings, Sheets sheets) {
        String sheetId = change.sheetId();
        LocalDate today = sheets.today(sheetId);
        if (change.setsClerkLimit()) setDated(settings, change, today, Settings.CLERK_LIMIT, change.clerkLimit());
        if (change.floor() != null) setDated(settings, change, today, Settings.FLOOR, change.floor());
        if (change.terms() != null) setDated(settings, change, today, Settings.TERMS, BigDecimal.valueOf(change.terms()));
        change.gradeTerms().forEach((grade, terms) -> setDated(settings, change, today, Settings.gradeKey(grade),
                terms != null ? BigDecimal.valueOf(terms) : null));
        change.gradeGrace().forEach((grade, days) -> setDated(settings, change, today, Settings.graceKey(grade),
                days != null ? BigDecimal.valueOf(days) : null));
        if (change.latePct() != null) setDated(settings, change, today, Settings.LATE_PCT, change.latePct());
        if (change.setsPolicyDate()) settings.setPolicyDate(sheetId, change.policyDate());
        if (change.setsCap()) setDated(settings, change, today, Settings.CAP, change.cap());
        if (change.setsProofThreshold()) setDated(settings, change, today, Settings.PROOF_THRESHOLD, change.proofThreshold());
        if (change.setsNoteThreshold()) setDated(settings, change, today, Settings.NOTE_THRESHOLD, change.noteThreshold());
        if (change.setsPeriodNumberingFrom()) settings.setPeriodNumberingFrom(sheetId, change.periodNumberingFrom());
        if (change.setsEntryDate()) settings.setEntryDate(sheetId, change.entryDate());
        if (change.setsGraceDays()) settings.setGraceDays(sheetId, change.graceDays());
        change.perms().forEach((action, roles) -> settings.setPermission(sheetId, action, roles));
    }

    private static void setDated(Settings settings, SettingsChange change, LocalDate today, String key, BigDecimal value) {
        settings.setDated(change.sheetId(), key, change.froms().getOrDefault(key, today), value);
    }
}
package net.officefloor.hq.app.settings;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the settings are saved, so a refused change writes no audit line. A line per setting
 *  set, a dated one ending in its from-date when one was given. */
public class RecordSettingChanged {
    public void record(@Val SettingsChange change, Audit audit) {
        String prefix = "SETTING_CHANGED sheet=" + change.sheetId() + " by=" + change.by();
        if (change.setsClerkLimit()) {
            audit.record(prefix + " key=clerk-limit value="
                    + (change.clerkLimit() != null ? change.clerkLimit().toPlainString() : "")
                    + from(change, Settings.CLERK_LIMIT));
        }
        if (change.floor() != null) {
            audit.record(prefix + " key=floor value=" + change.floor().toPlainString() + from(change, Settings.FLOOR));
        }
        if (change.terms() != null) {
            audit.record(prefix + " key=terms value=" + change.terms() + from(change, Settings.TERMS));
        }
        change.gradeTerms().forEach((grade, terms) ->
                audit.record(prefix + " key=terms-" + grade + " value=" + (terms != null ? terms : "")
                        + from(change, Settings.gradeKey(grade))));
        change.gradeGrace().forEach((grade, days) ->
                audit.record(prefix + " key=" + Settings.graceKey(grade) + " value=" + (days != null ? days : "")
                        + from(change, Settings.graceKey(grade))));
        if (change.latePct() != null) {
            audit.record(prefix + " key=late-pct value=" + change.latePct().toPlainString() + from(change, Settings.LATE_PCT));
        }
        if (change.setsPolicyDate()) {
            audit.record(prefix + " key=policy-date value="
                    + (change.policyDate() != null ? change.policyDate().toString() : ""));
        }
        if (change.setsPeriodNumberingFrom()) {
            audit.record(prefix + " key=period-numbering-from value="
                    + (change.periodNumberingFrom() != null ? change.periodNumberingFrom().toString() : ""));
        }
        if (change.setsCap()) {
            audit.record(prefix + " key=cap value=" + (change.cap() != null ? change.cap().toPlainString() : "")
                    + from(change, Settings.CAP));
        }
        if (change.setsProofThreshold()) {
            audit.record(prefix + " key=proof-threshold value="
                    + (change.proofThreshold() != null ? change.proofThreshold().toPlainString() : "")
                    + from(change, Settings.PROOF_THRESHOLD));
        }
        if (change.setsNoteThreshold()) {
            audit.record(prefix + " key=note-threshold value="
                    + (change.noteThreshold() != null ? change.noteThreshold().toPlainString() : "")
                    + from(change, Settings.NOTE_THRESHOLD));
        }
        change.perms().forEach((action, roles) ->
                audit.record(prefix + " key=" + Settings.permKey(action) + " value=" + (roles != null ? roles : "")));
        if (change.setsGraceDays()) {
            audit.record(prefix + " key=grace-days value=" + (change.graceDays() != null ? change.graceDays() : ""));
        }
        if (change.setsEntryDate()) {
            audit.record(prefix + " key=entry-date value="
                    + (change.entryDate() != null ? change.entryDate().toString() : ""));
        }
    }

    /** " from=<date>" when a from-date was given for the key, else nothing. */
    private static String from(SettingsChange change, String key) {
        LocalDate from = change.froms().get(key);
        return from != null ? " from=" + from : "";
    }
}

