import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Late } from '../claims/useClaims';
import { useSheetToday } from '../sheet/useSheet';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';
import { gradeOn, usePeople } from '../people/usePeople';

/** A role given to a user name: clerk (the default for any name) or steward. */
export type RoleEntry = { name: string; role: string };

/** The sheet's settings as the server sends them: `clerkLimit` with two decimals, or null for no
 *  limit, `floor` with two decimals `terms` in days, `latePct` with two decimals and `policyDate` as
 *  set (yyyy-mm-dd), or null when blank: then the policy date is the sheet's today, and `periodNumberingFrom`
 *  (yyyy-mm-dd), or null when off, and `gradeTerms` the terms set per grade (a grade not in it uses the
 *  sheet's terms), and `cap` with two decimals, or null for no cap — each dated one as in force on the
 *  sheet's today; and `dated`, every value recorded for the dated settings by key (clerk-limit, floor,
 *  terms, terms-<grade>, grace-<grade>, late-pct, cap, proof-threshold, note-threshold), oldest from-date first; and `proofThreshold` with
 *  two decimals, or null for none, as in force on the sheet's today; and `perms`, the roles set for each
 *  action of the permission matrix, comma separated (an action not in it keeps the standing rule); and `graceDays`, the grace days, or null when off (not dated); and `delegations`, every delegation of the steward role, oldest first; and `noteThreshold` with two decimals, or null for none, as in force on the sheet's today; and `entryDate` (yyyy-mm-dd), or null when off: while set, the default date of a new claim in place of the sheet's today (not dated); and `gradeGrace`, the grace days set per grade in force on the sheet's today (a grade not in it has none; dated, under grace-<grade>). */
/** A delegation of the steward role: the user acts as a steward while the sheet's today is from
 *  `from` to `to` (yyyy-mm-dd, inclusive), for the steward `by` who delegated. */
export type DelegationEntry = { name: string; from: string; to: string; by: string };

export type Settings = { clerkLimit: string | null; floor: string; terms: number; latePct: string; policyDate: string | null; periodNumberingFrom: string | null; gradeTerms: Record<string, number>; cap: string | null; roles: RoleEntry[]; dated: Record<string, DatedValue[]>; proofThreshold: string | null; noteThreshold: string | null; perms: Record<string, string>; graceDays: number | null; delegations: DelegationEntry[]; entryDate: string | null; gradeGrace: Record<string, number> };

/** A dated setting's value from a from-date (yyyy-mm-dd); null for blank. */
export type DatedValue = { from: string; value: string | null };

/** The floor of a sheet that has not set one. */
export const DEFAULT_FLOOR = '1.00';

/** The terms, in days, of a sheet that has not set them. */
export const DEFAULT_TERMS = 14;

export const settingsKey = (sheet: string) => ['sheet', sheet, 'settings'] as const;

/** The sheet's settings, re-read whenever the sheet is loaded. */
export function useSettings(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(settingsKey(sheet), asOf),
    queryFn: () => getJson<Settings>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/settings`, asOf)),
    staleTime: 0,
    gcTime: 0,
  });
}

/** The value of a dated setting in force on `date`: the one with the latest from-date on or before
 *  it, else `start` (the setting's starting value; null when it has none). A blank value is null. */
export function valueOn(settings: Settings | undefined, key: string, date: string, start: string | null): string | null {
  let found: DatedValue | undefined;
  for (const v of settings?.dated?.[key] ?? []) if (v.from <= date) found = v;
  return found === undefined ? start : (found.value ?? start);
}

/** The sheet's floor in force on a date: a claim's live due is at least the one on its date. */
export type FloorOn = (date: string) => string;

/** The sheet's floor, by date. */
export function useFloor(sheet: string): FloorOn {
  const settings = useSettings(sheet).data;
  return (date) => valueOn(settings, 'floor', date, DEFAULT_FLOOR) ?? DEFAULT_FLOOR;
}

/** The sheet's cap in force on its today: a person's due-total is at most it. Null for no cap. */
export function useCap(sheet: string): string | null {
  const settings = useSettings(sheet).data;
  const today = useSheetToday(sheet);
  return today === '' ? (settings?.cap ?? null) : valueOn(settings, 'cap', today, null);
}

/** The sheet's terms: a claim is due by its date plus this many days. */
export function useTerms(sheet: string): number {
  return useSettings(sheet).data?.terms ?? DEFAULT_TERMS;
}

/** The late percent of a sheet that has not set one. */
export const DEFAULT_LATE_PCT = '0.00';

/** What makes an overdue claim's due grow: the sheet's today and its late percent, by date; and a
 *  claim's grace days: those of its person's grade in force on its date, in force on that date. */
export function useLate(sheet: string): Late {
  const settings = useSettings(sheet).data;
  const { data: people = [] } = usePeople(sheet);
  return {
    today: useSheetToday(sheet),
    pctOn: (date) => valueOn(settings, 'late-pct', date, DEFAULT_LATE_PCT) ?? DEFAULT_LATE_PCT,
    graceOn: (claim) => {
      const person = people.find((p) => p.id === claim.personId);
      if (person === undefined) return 0;
      const days = valueOn(settings, `grace-${gradeOn(person, claim.date)}`, claim.date, null);
      return days === null ? 0 : Number(days);
    },
  };
}

export const ROLES = ['clerk', 'steward', 'viewer'] as const;

/** A clerk limit the server accepts: an amount with up to two decimals, or blank for no limit. */
export const LIMIT = /^(\d{1,10}(\.\d{1,2})?)?$/;

/** A late percent the server accepts: a percent with up to two decimals, or blank for 0.00. */
export const PERCENT = /^(\d{1,5}(\.\d{1,2})?)?$/;

/** A policy date the server accepts: yyyy-mm-dd, or blank for the sheet's today. */
export const POLICY_DATE = /^(\d{4}-\d{2}-\d{2})?$/;

/** The grades terms can be set for. */
export const TERM_GRADES = ['A', 'B', 'C'] as const;

/** Terms the server accepts: a whole number of days, or blank for the default 14. */
export const DAYS = /^(\d{1,4})?$/;

/** A from-date the server accepts: yyyy-mm-dd (a blank one is not sent: the sheet's today). */
export const FROM_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** The actions of the permission matrix: each may be given the roles allowed to take it. */
export const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;

/** A permission the server accepts: a comma separated list of roles, or blank for the standing rule. */
export const PERM_ROLES = /^(\s*(clerk|steward)\s*(,\s*(clerk|steward)\s*)*)?$/i;
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { claimsKey } from '../claims/useClaims';
import { DAYS, FROM_DATE, TERM_GRADES, LIMIT, PERCENT, PERM_ACTIONS, PERM_ROLES, POLICY_DATE, ROLES, settingsKey, useSettings, type Settings } from './useSettings';

/** The settings the form sets: each null while its field is untouched, so a save leaves it as it is. */
type SettingsEdit = { clerkLimit: string | null; floor: string | null; terms: string | null; latePct: string | null; policyDate: string | null; periodNumberingFrom: string | null; cap: string | null; proofThreshold: string | null; noteThreshold: string | null; graceDays: string | null; entryDate: string | null; gradeTerms: Record<string, string>; gradeGrace: Record<string, string>; perms: Record<string, string> };

/** The from-date typed for each dated setting, by key (blank: from the sheet's today). */
type Froms = Record<string, string>;

/**
 * The sheet's settings: its clerk limit (a clerk settles a claim only when its due is at or below
 * it; blank is no limit), its floor (a claim's live due is at least it; blank is the default, 1.00),
 * its terms (a claim is due by its date plus this many days; blank is the default, 14), the terms
 * of each grade (a claim of a person of that grade is due by them; blank uses the sheet's terms), its late
 * percent (an overdue claim's due gains it of its figure for every full 30 days; blank is 0.00),
 * its policy date (a claim dated before it rounds half up, on or after it half to even; blank is
 * the sheet's today), its period numbering from (while it is a date on or before the sheet's
 * today, a claim opened is numbered within its period; blank is off), its cap (a person's due-total
 * is at most it, the rest their excess; blank is no cap), its proof threshold (a claim whose due is above
 * the one on its date cannot be settled or approved without a proof; blank is none), its note threshold (a claim
 * whose due is above the one on its date cannot be opened with an empty note; blank is none),
 * its permission matrix (for each of open, settle, void, reassign, close and reopen, the roles that may
 * take it, comma separated; blank keeps the standing rule: open, settle, void and close by clerk and
 * steward, reassign and reopen by steward; not dated), its grace days (when its today is changed, every open
 * period whose to-date plus them is before the new today is closed; blank is off; not dated),
 * the grace days of each grade (a claim of a person of that grade on its date is overdue, and its late
 * charge counted, only from its due-by plus the grace in force on its date; blank is none),
 * its entry date (while set, the default date of a new claim in place of the sheet's today; blank is off; not dated),
 * and the roles given to user names (clerk, the default, steward, or viewer — who sees everything and can change nothing),
 * and the delegations of the steward role (a steward delegates it to a user from a from-date to a to-date, inclusive,
 * by the sheet's today; a blank from-date is the sheet's today, a blank to-date the from-date). A save sets only the settings
 * whose fields were touched since the last one. The clerk limit, the floor, the terms (the sheet's and
 * each grade's), the grace days of each grade, the late percent, the cap, the proof threshold and the note threshold are dated: a save records each from its from-date (blank
 * is the sheet's today), and each shows the value in force on the sheet's today.
 */
function SettingsPanel({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data } = useSettings(sheet);
  const base = `/api/sheets/${encodeURIComponent(sheet)}`;
  const [edit, setEdit] = useState<SettingsEdit>({ clerkLimit: null, floor: null, terms: null, latePct: null, policyDate: null, periodNumberingFrom: null, cap: null, proofThreshold: null, noteThreshold: null, graceDays: null, entryDate: null, gradeTerms: {}, gradeGrace: {}, perms: {} });
  const [froms, setFroms] = useState<Froms>({});
  const [limitInvalid, setLimitInvalid] = useState(false);
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [roleInvalid, setRoleInvalid] = useState(false);
  const [delegate, setDelegate] = useState({ name: '', from: '', to: '' });
  const [delegateInvalid, setDelegateInvalid] = useState(false);

  const submitOnce = useSubmitOnce();
  const saveSettings = useMutation({
    mutationFn: ({ e, from }: { e: SettingsEdit; from: Froms }) => postJson<Settings>(`${base}/settings`, { ...e, from, user }),
    onSuccess: (saved) => {
      setEdit({ clerkLimit: null, floor: null, terms: null, latePct: null, policyDate: null, periodNumberingFrom: null, cap: null, proofThreshold: null, noteThreshold: null, graceDays: null, entryDate: null, gradeTerms: {}, gradeGrace: {}, perms: {} });
      setFroms({});
      queryClient.setQueryData(settingsKey(sheet), saved);
      // The policy date decides how each claim's live figures round.
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });
  const saveRole = useMutation({
    mutationFn: (r: { name: string; role: string }) => postJson<Settings>(`${base}/roles`, { ...r, user }),
    onSuccess: (saved) => {
      setName('');
      setRole('');
      queryClient.setQueryData(settingsKey(sheet), saved);
    },
  });

  const saveDelegation = useMutation({
    mutationFn: (d: { name: string; from: string; to: string }) => postJson<Settings>(`${base}/delegations`, { ...d, user }),
    onSuccess: (saved) => {
      setDelegate({ name: '', from: '', to: '' });
      queryClient.setQueryData(settingsKey(sheet), saved);
    },
  });

  // An error goes as soon as its form is changed or submitted again.
  const clearSettingsError = () => {
    saveSettings.reset();
    setLimitInvalid(false);
  };
